#[component]
pub fn Icon(name: String, #[props(default = 20)] size: u32) -> Element {
    let svg = format!(
        "<svg viewBox=\"0 0 24 24\" width=\"{size}\" height=\"{size}\" aria-hidden=\"true\"><path fill=\"currentColor\" d=\"{}\"/></svg>",
        path(&name)
    );
    rsx! {
        span { class: "icon", dangerous_inner_html: "{svg}" }
    }
}

